// subscriptionEventTypes maps subscription-only event kinds to their payload.
func decodeSubscriptionEvent(kind string, b []byte) (any, bool, error) {
	switch kind {
	case "pane.output_matched":
		var v PaneOutputMatchedEvent
		err := json.Unmarshal(b, &v)
		return v, true, err
	case "pane.agent_status_changed":
		var v PaneAgentStatusChangedEvent
		err := json.Unmarshal(b, &v)
		return v, true, err
	case "pane.scroll_changed":
		var v PaneScrollChangedEvent
		err := json.Unmarshal(b, &v)
		return v, true, err
	}
	return nil, false, nil
}

// DecodeSubscriptionEvent decodes the data of a subscription-only event
// (see SubscriptionEventKind). ok is false for other kinds.
func DecodeSubscriptionEvent(kind string, data []byte) (v any, ok bool, err error) {
	return decodeSubscriptionEvent(kind, data)
}
